import {ages,weights,medications,pediatricTubes,igelForWeight,igelSource} from './data.js';
import {pediatricDose} from './pediatric-ui.js';
import {selectedShockDevice,shockDevicePicker} from './defib-guide.js';
import {kgFrom} from './calculations.js';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n.toFixed(3)).toString();
const aha='https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/neonatal-resuscitation';
const ahaLink=()=>`<a class="source" href="${aha}" target="_blank" rel="noopener">AHA / AAP · 2025 NEWBORN ↗</a>`;
const lines=items=>`<ul class="leader-lines">${items.map(([lead,detail])=>`<li><b>${lead}</b>${detail?`<span>${detail}</span>`:''}</li>`).join('')}</ul>`;
const block=(number,title,color,body,refs='')=>`<section class="leader-block" data-priority="${color}"><div class="leader-heading"><h2><span>${number}</span>${title}</h2>${refs?`<div class="leader-sources">${refs}</div>`:''}</div><div class="leader-content">${body}</div></section>`;
const numberTile=(label,value,unit='',note='')=>`<div class="leader-number"><span>${label}</span><strong>${value}<small>${unit}</small></strong>${note?`<p>${note}</p>`:''}</div>`;

export function arrestWeight(state){
 const f=state.fields,actual=f['peds-arrest-weight'];
 if(actual!==undefined&&String(actual).trim()!==''){
  const kg=kgFrom(actual,f['peds-arrest-unit']||'kg');
  return Number.isFinite(kg)&&kg>0&&kg<=150?{kg,mode:'actual',index:weights.indexOf(kg)}:{kg:null,mode:'invalid',index:-1};
 }
 const index=Number.isInteger(state.age)&&state.age>=0&&state.age<weights.length?state.age:-1;
 return {kg:index<0?null:weights[index],mode:index<0?'empty':'estimate',index};
}

const arrestDrugs=[
 {name:'Epinephrine',row:'Epinephrine · cardiac arrest',color:'red',stock:.1,rule:kg=>Math.min(.01*kg,1),formula:'0.01 mg/kg · maximum 1 mg',note:'IV / IO · repeat every 3–5 min. Arrest syringe: 0.1 mg/mL (1 mg / 10 mL).',page:152},
 {name:'Amiodarone',row:'Amiodarone · cardiac arrest',color:'purple',stock:50,rule:kg=>Math.min(5*kg,300),formula:'5 mg/kg · maximum 300 mg',note:'VF / pulseless VT only. IV / IO; may repeat up to 2 times for refractory VF / pVT.',page:152},
 {name:'Lidocaine · arrest alternative',row:'Lidocaine · cardiac arrest',color:'teal',stock:20,rule:kg=>kg,formula:'1 mg/kg IV / IO push',note:'VF / pulseless VT: may substitute for amiodarone. This is the arrest dose, not IO pain-control dosing. Volume below uses 2% (20 mg/mL); verify the label.',page:152},
 {name:'Normal saline',row:'Normal saline bolus',color:'blue',stock:null,rule:kg=>20*kg,formula:'20 mL/kg IV / IO',note:'P602 PEA / asystole bolus. Reassess perfusion; additional boluses under medical control.',page:153}
];
export function arrestDose(drug,weight){
 if(!weight.kg)return null;
 const row=medications.find(m=>m.name===drug.row);
 if(weight.index>=0){const d=pediatricDose(row,weight.index);return {...d,table:true};}
 const amount=drug.rule(weight.kg),unit=drug.stock?'mg':'mL';
 return {amount,unit,volume:drug.stock?amount/drug.stock:amount,table:false};
}
function drugCards(state,source){const weight=arrestWeight(state);return `<div class="critical-grid arrest-drugs">${arrestDrugs.map(drug=>{
 const d=arrestDose(drug,weight);
 return `<article class="critical-card" data-priority="${drug.color}" data-arrest-drug="${drug.row}"><h3>${drug.name}</h3><div class="critical-dose"><div><b>${drug.formula}</b><div class="critical-route"><span class="critical-route-badge">IV</span><span class="critical-route-badge">IO</span></div>${drug.stock?`<small>${drug.stock} mg/mL · verify stock</small>`:''}</div><div class="critical-value">${d?`<b>${fmt(d.amount)} <small>${d.unit}</small></b>${drug.stock?`<span>${fmt(d.volume)} mL</span>`:''}`:'<b class="dose-unavailable">Select weight</b>'}</div></div><p>${drug.note}</p>${d?.table?'<p>Appendix J dose and volume as printed.</p>':''}${d?.table&&drug.row==='Amiodarone · cardiac arrest'&&weight.kg===15?'<p class="dose-discrepancy"><b>Printed table: 75 mg / 1.55 mL.</b> At 50 mg/mL, 75 mg converts to 1.5 mL. Confirm this source discrepancy before administration.</p>':''}<div class="critical-links">${source(drug.row==='Normal saline bolus'?'P602':'P601',drug.page)}${d?.table?source('APPENDIX J',rowPage(drug.row)):''}</div></article>`;
 }).join('')}</div><div class="leader-caution"><b>Read back drug, dose, concentration, route, and volume.</b> Use only the indicated arrest pathway. Other stock concentrations require a separate volume calculation. ETT epinephrine uses a different concentration: ${source('ETT · P601 / P602',152)}</div>`;}
function rowPage(name){return medications.find(m=>m.name===name).page;}
function weightPanel(state,source){const f=state.fields,w=arrestWeight(state),device=selectedShockDevice(f),kg=w.kg,igels=igelForWeight(kg);
 return block('02','Weight, airway & shock energy','teal',`<div class="leader-weight-fields"><label class="field">Actual weight<input id="peds-arrest-weight" data-ref-field="peds-arrest-weight" type="number" min="0" step="any" inputmode="decimal" placeholder="If known" value="${esc(f['peds-arrest-weight'])}"></label><label class="field">Units<select id="peds-arrest-unit" data-ref-field="peds-arrest-unit"><option value="kg" ${f['peds-arrest-unit']!=='lb'?'selected':''}>kg</option><option value="lb" ${f['peds-arrest-unit']==='lb'?'selected':''}>lb</option></select></label></div><div class="age-grid">${ages.map((a,i)=>`<button data-age="${i}" aria-pressed="${state.age===i}" class="${state.age===i?'selected':''}"><b>${a}</b><span>${weights[i]} kg estimate</span></button>`).join('')}</div><p class="leader-weight-status" role="status">${w.mode==='invalid'?'Enter a valid weight greater than 0 and no more than 150 kg. Values cleared.':kg?`<b>${fmt(kg)} kg · ${w.mode==='actual'?'actual weight':'age estimate'}</b>${w.mode==='actual'?' · Age buttons do not override entered actual weight.':' · Confirm weight with Broselow / length-based assessment.'}`:'Enter actual weight, or select an age estimate.'}</p><p class="leader-help">Age buttons share the Pediatric calculator selection. Clear actual weight to use that estimate. Exact chart weights retain Appendix J doses / volumes; other weights use P601 / P602 formulas. This pathway applies to patients younger than 16.</p><div class="leader-airway">${numberTile('ET TUBE · APP J',w.index>=0?pediatricTubes[w.index]:'Use Broselow',w.index>=0?'mm':'',w.index<0?'No airway-size interpolation.':'Match anatomy; confirm placement.')}${numberTile('i-gel · WEIGHT RANGE',igels.map(s=>s.size).join(' / ')||'—','','Match actual weight and anatomy.')}</div><div class="leader-sources">${source('AIRWAY · T706',193)}<a class="source" href="${igelSource}" target="_blank" rel="noopener">i-gel SIZE GUIDE ↗</a></div>${shockDevicePicker(f)}<div class="leader-energy">${numberTile('FIRST SHOCK · 2 J/kg',kg?Math.min(Math.ceil(2*kg),device.max):'—','J')}${numberTile('SECOND · 4 J/kg',kg?Math.min(Math.ceil(4*kg),device.max):'—','J')}${numberTile('LATER · 4–10 J/kg',kg?`${Math.min(Math.ceil(4*kg),device.max)}${4*kg>=device.max?'':'–'+Math.min(Math.ceil(10*kg),device.max)}`:'—','J')}</div><p class="leader-help"><b>VF / pulseless VT · unsynchronized.</b> Round up; do not exceed ${device.max} J on ${device.name}. Pre-charge during CPR, clear everyone, shock only a shockable rhythm, then immediately resume CPR.</p>`,source('P601',152)+source('APPENDIX J',237));
}

export function neonatalPanel(state,source,birth=false){const key=birth?'birth-neonatal':'arrest-neonatal';return `<details class="neonatal-code" data-code-open="${key}" ${state.fields[key+'-open']?'open':''}><summary><span><b>Neonatal code</b><small>${birth?'Just delivered · newborn transition · baby team':'Newborn resuscitation · P600 · expand for delivery-related code'}</small></span><span class="expand-symbol" aria-hidden="true">+</span></summary><div class="neonatal-content"><p class="neonatal-context"><b>${birth?'Baby just delivered: assess breathing, tone, and heart rate immediately.':'Use P600 for the newborn at birth. An infant arrest outside delivery follows the main pediatric pathway. The 2-minute pediatric CPR timer does not time neonatal reassessment.'}</b> Call for ALS / additional neonatal help early.</p><div class="leader-sources">${source('NEWBORN · P600',151)}${birth?source('DELIVERY · O800',213):''}${ahaLink()}</div>${block('01','Dry, warm & assess','blue',lines([
 ['Move to a warm, firm surface; dry and stimulate.','Remove wet linens, cover the head, position the airway, and reassess breathing and heart rate.'],
 ['Assess heart rate; right-hand / wrist pulse oximeter.','P600: listen to the heart or palpate the cord. Monitor heart rate, breathing, and oxygenation together.'],
 ['Clear an obstructed airway without delaying ventilation.','2025 AHA: routine suction is not recommended, including for meconium. P600 suction wording differs; use the service-approved approach.']
 ]))}${block('02','Apnea / gasping or HR <100 → ventilate','teal',`<div class="neonatal-threshold"><strong>HR &lt;100</strong><b>BVM · 60 breaths/min</b></div>${lines([
 ['P600: begin with ROOM AIR.','Use only enough pressure for chest rise. Reassess after 30 seconds of effective ventilation.'],
 ['No chest rise / HR not improving: correct ventilation.','Reposition, improve the seal, assess obstruction, and consider an alternate airway. Ventilation is the priority.'],
 ['If intubating: term 3.0–3.5 mm; premature 2.5–3.0 mm.','Confirm exhaled CO₂, document depth at the gum, secure, and repeatedly recheck position.'],
 ['HR ≥100 with adequate breathing: monitor and reassess.','Titrate any supplemental oxygen using right-upper-extremity SpO₂. Prematurity-specific oxygen guidance: open AHA / service protocol.']
 ])}`)}${block('03','HR <60 after effective ventilation → 3:1','red',`<div class="neonatal-threshold"><strong>HR &lt;60</strong><b>3 compressions : 1 breath</b></div>${lines([
 ['After 30 seconds of ventilation that moves the chest, begin coordinated compressions.','Use the 2-thumb encircling technique. Keep ventilation effective; reassess heart rate.'],
 ['Persistent HR <60: vascular access, epinephrine, medical control.','Repeat epinephrine every 3–5 minutes per the confirmed neonatal order. Do not use the pediatric age table for newborn epinephrine.']
 ])}<div class="leader-caution"><b>P600 requires clarification before neonatal medication dosing.</b> Its ETT dose / concentration / volume do not agree, and its preterm IV volume differs from the stated fixed dose. No neonatal epinephrine dose is calculated here. Confirm dose, route, concentration, volume, and escalation timing with medical control.</div><p class="leader-help">P600 lists 30 seconds of compressions before considering epi and 120 compressions/min. Current AHA uses 60 seconds of coordinated compressions / ventilation before epi and 90 compressions + 30 breaths/min; increase oxygen to 100% during compressions. Confirm the service-approved standard.</p>`,source('P600 · VERIFY',151)+ahaLink())}${block('04','Blood loss, reassessment & transport','purple',lines([
 ['Suspected hypovolemia from blood loss at delivery: NS 20 mL/kg IV per P600.','Use actual newborn weight; P600’s approximate term / preterm volumes do not match its weight formula. Confirm the volume with medical control.'],
 ['Keep reassessing HR, breathing, oxygenation, and tube position.','HR ≥60: stop compressions and continue assisted ventilation if needed; adequate HR / breathing: monitor.'],
 ['Update medical control and notify the receiving hospital.','Report birth time, gestational age, ventilation / CPR duration, response, and medications. Prematurity / resuscitation decisions require medical control.'],
 ['Plan safe transport for mother and baby.','Use an approved neonatal restraint; coordinate destination and additional resources. P600 advises against active warming after prolonged term resuscitation—confirm with medical control.']
 ]),source('P600',151)+source('TRANSPORT · O801',216))}</div></details>`;}

export function pediatricArrest(state,source,icon,timers){return `<div class="leader-page"><div class="page-heading"><div><h1>Pediatric cardiac arrest</h1><p>En route preparation · team leader on scene · younger than 16 years</p></div><div class="large-icon red">${icon('child')}</div></div><div class="leader-shortcuts"><button data-leader-scroll="peds-weight">Weight & doses ↓</button><button data-leader-scroll="peds-code">Run the code ↓</button><button data-leader-scroll="peds-timers">CPR / epi timers ↓</button></div>${block('01','Arrive ready','blue',lines([
 ['Turn main O₂ AND cabin power on.','Bring pediatric BVM / masks, suction, airway bag, monitor / pediatric pads, drug bag, IV / IO supplies, and Broselow tape.'],
 ['Name the leader and assign roles out loud.','Airway · compressions / rotations · monitor · access / meds · timer / recorder · family support.'],
 ['Get age, estimated weight, and arrest circumstances en route.','Delivery-related newborn? Open Neonatal code. Infant / child arrest? Continue below.']
 ]),source('SB204',50)+source('P601',152)+source('P602',153))}${neonatalPanel(state,source)}<div id="peds-weight">${weightPanel(state,source)}</div><div id="peds-code">${block('03','Run the code','red',`<div class="leader-metrics">${numberTile('COMPRESSIONS','100–120','/min','≥⅓ chest depth · full recoil')}${numberTile('2 RESCUERS · PREPUBERTAL','15:2','','Single rescuer: 30:2')}${numberTile('ADVANCED AIRWAY','20–30','breaths/min','Continuous CPR · SB204 note E')}</div>${lines([
 ['CPR on a firm surface; pads connected; BVM with visible chest rise.','Minimize interruptions, use oxygen, monitor ETCO₂, establish IV / IO, and rotate compressors every 2 minutes. Pubertal patients: 30:2 without an advanced airway.'],
 ['Recheck rhythm / pulse every 2 minutes.','Keep compressions going while charging. Clear before a shock; disarm if nonshockable.']
 ])}<div class="leader-rhythm-grid"><article data-priority="orange"><h3>VF / pulseless VT</h3>${lines([['Defibrillate using the weight-based sequence above.','Immediately resume CPR for 2 minutes.'],['Epinephrine IV / IO every 3–5 minutes.','Amiodarone for VF / pVT; lidocaine may substitute.'],['Arrange early transport after resuscitation begins.','Notify the receiving hospital; reassess rhythm and response.']])}${source('SHOCKABLE · P601',152)}</article><article data-priority="purple"><h3>PEA / asystole</h3>${lines([['CPR + effective ventilation; do not shock.','Confirm asystole in 2 or more leads.'],['Epinephrine IV / IO every 3–5 minutes.','NS 20 mL/kg; reassess.'],['Check glucose and correct reversible causes.','Contact medical control for additional fluids / procedures and transport decisions.']])}${source('NONSHOCKABLE · P602',153)}</article></div>`,source('SB204 · CPR',50)+source('PEDIATRIC VENTILATION · NOTE E',51))}</div>${block('04','Arrest medications','purple',drugCards(state,source),source('APPENDIX J',237))}<div id="peds-timers" class="leader-timers">${timers}</div>${block('05','Reassess, ROSC & destination','teal',lines([
 ['Treat the reversible cause while the code continues.','Hypoxia · hypovolemia · acidosis · potassium · hypothermia · toxins · tamponade · tension pneumothorax · thrombosis · trauma.'],
 ['Pulse returns: switch to post-ROSC care.','Recheck airway / ETCO₂, oxygenation, BP / perfusion, and glucose. Keep monitoring / pads on and notify hospital.'],
 ['Poor perfusion + bradycardia with a pulse: open P603.','Correct oxygenation / ventilation first; P603 directs compressions for persistent HR <60 despite adequate support.'],
 ['Plan movement and destination with medical control.','Use rhythm-specific transport guidance. Pediatric termination decisions require A105 / medical control. Traumatic arrest follows S509.']
 ]),source('POST-ROSC · C307',83)+source('BRADYCARDIA · P603',154)+source('TRAUMATIC ARREST · S509',148)+source('A105',20))}<div class="leader-related"><button class="button" data-page="pediatric">Full pediatric calculator</button><button class="button" data-page="birth">Imminent birth</button></div></div>`;}

export function imminentBirth(state,source,icon){return `<div class="leader-page"><div class="page-heading"><div><h1>Imminent birth</h1><p>En route preparation · maternal team + baby team · leader on scene</p></div><div class="large-icon teal">${icon('child')}</div></div><div class="leader-shortcuts"><button data-leader-scroll="birth-delivery">Delivery ↓</button><button data-leader-scroll="birth-newborn">Neonatal code ↓</button><button data-leader-scroll="birth-eclampsia">Eclampsia ↓</button></div>${block('01','Arrive ready for two patients','blue',lines([
 ['Turn cabin power on; warm the cabin and stage the OB kit.','PPE, clean towels / dry blankets / hat, clamps / scissors, newborn BVM / masks, suction, monitor / right-hand SpO₂, and IV / IO supplies. Main O₂ available; newborn initial BVM uses room air per P600.'],
 ['Assign a maternal team and a newborn team.','Ask for additional ALS / manpower early. Name who receives and assesses the baby.'],
 ['Ask due date / gestational age, gravida / para, prior delivery problems.','Contraction frequency, urge to push, crowning / presenting part, bleeding, ruptured membranes / meconium, multiples, seizure / hypertension.'],
 ['Crowning / fetal part visible + urge to push: prepare to deliver on scene.','If delivery is not imminent, transport promptly to appropriate maternity services. Establish IV if time permits; protect privacy.']
 ]),source('IMMINENT DELIVERY · O800',213))}<div id="birth-delivery">${block('02','Deliver & care for mother and baby','teal',lines([
 ['Support the head and perineum as the head crowns.','Control emergence gently. Remove membranes covering the face. Avoid pulling on the baby.'],
 ['Check for a cord around the neck.','Try to slip it over the head or shoulders. Clamp / cut only as a last resort for a tight cord that cannot be reduced—follow O800.'],
 ['Support rotation and delivery of the shoulders, then the body.','Guide gently as described in O800; hand the baby to the assigned provider and record birth time.'],
 ['Vigorous baby: O800 delays cord clamping 30–60 seconds.','Resuscitation takes priority for respiratory / circulatory depression. Current AHA recommends at least 60 seconds if immediate resuscitation is unnecessary; confirm service policy.'],
 ['O800: clamp ~4 inches from baby, second clamp ~2 inches farther toward mother; cut between.','Stable baby: dry / warm, skin-to-skin, reassess breathing and tone. Use an approved neonatal restraint for transport.'],
 ['Do not pull on the cord or wait for placenta delivery before transport.','If the placenta delivers, bag it and bring it. Recheck maternal BP / perfusion, uterine tone, and bleeding; notify the receiving hospital.']
 ]),source('O800 · DELIVERY',213)+source('CORD / PLACENTA',214))}</div><div id="birth-newborn">${neonatalPanel(state,source,true)}</div><div id="birth-eclampsia">${block('03','Eclampsia / severe hypertension','purple',`${lines([
 ['Pregnant or recent postpartum + seizure: consider eclampsia.','Headache, visual change, RUQ / epigastric pain, or severe BP may precede seizures. Eclampsia can occur through 6 weeks postpartum.'],
 ['Protect airway, prevent injury / hypoxia; left lateral tilt if pregnant.','Get IV access, glucose, ECG, SpO₂, BP, and ETCO₂; transport to 24/7 maternity services.']
 ])}<div class="critical-grid birth-drugs"><article class="critical-card" data-priority="red"><h3>Active seizure → Versed first</h3><div class="birth-drug-body"><b>Age 16+ · M410</b><p><strong>10 mg IM</strong> · single dose, preferred.</p><p><strong>5–10 mg IN</strong> or <strong>2–5 mg IV / IO</strong>; repeat every 10 min until seizure resolves, maximum 10 mg total for these routes.</p><p>Use pediatric P610 dosing if younger than 16; do not use these fixed adult doses.</p><p><b>Support breathing; continuous ETCO₂.</b></p></div><div class="critical-links">${source('M410',106)}${source('P610 · UNDER 16',164)}</div></article><article class="critical-card" data-priority="purple"><h3>Eclampsia → magnesium</h3><div class="birth-drug-body"><strong>4–6 g IV over 20–25 min</strong><p>Give even when the seizure has stopped. O802: mix in 100 mL NS; verify stock and final preparation.</p><p><b>5 g / 10 mL stock:</b> 4–6 g = <strong>8–12 mL drawn up</strong>. Draw volume is not the infusion volume. IV preferred when available.</p><p><b>No IV:</b> O802 alternative is 10 g deep IM total, two 5 g injections, one per buttock, Z-track / 3-inch needle.</p><p><b>Contraindicated with myasthenia gravis.</b> Monitor for hypotension. Magnesium + Versed can severely depress breathing.</p></div><div class="critical-links">${source('O802 · MAGNESIUM',218)}<button class="button small" data-page="medications" data-reference-open="magnesium">Open magnesium guide</button></div></article></div><div class="leader-caution"><b>Sustained BP ≥160 systolic and/or ≥110 diastolic, twice ≥15 min apart:</b> O802 antihypertensive threshold. Nifedipine 10 mg PO; repeat BP in 15 min. If still severe, repeat 10 mg PO to maximum 3 doses; notify hospital. Verify availability and ability to take PO. ${source('O802 · SEVERE BP',219)}</div>`,source('ECLAMPSIA · O802',218))}</div>${block('04','Delivery complications & bleeding','red',`<div class="leader-rhythm-grid"><article data-priority="orange"><h3>Shoulders stuck / prolapsed cord</h3>${lines([
 ['Shoulder dystocia: McRoberts + suprapubic pressure.','No fundal pressure for shoulder dystocia; never pull on the head. Escalate per O801.'],
 ['Prolapsed cord: gloved hand lifts presenting part off the cord.','Elevate maternal hips, keep cord moist, oxygen for mother, and transport urgently while relieving pressure.'],
 ['Breech / other malpresentation: call for ALS / medical control.','Use O801 maneuvers if delivery is unavoidable; otherwise urgent transport.']
 ])}${source('O801 · COMPLICATIONS',215)}</article><article data-priority="red"><h3>Postpartum hemorrhage</h3>${lines([
 ['Heavy bleeding / poor perfusion: call for help and rapid transport.','Monitor blood loss / vitals, pressure on active bleeding sites, and assess uterine tone.'],
 ['Massage uterine fundus for uterine atony.','Continue until firm / bleeding abates. Persistent bleeding with a firm uterus needs other hemorrhage control.'],
 ['ALS: adequate IV access, crystalloid, TXA per S506.','Two IVs if possible, at least one large bore. Notify hospital immediately.']
 ])}${source('O801 · HEMORRHAGE',216)}${source('TXA · S506',144)}</article></div>`,source('O801',215)+source('O802',218))}${block('05','Destination & handoff','blue',lines([
 ['Notify the hospital; coordinate mother and baby together when possible.','24/7 labor and delivery. Maternal instability / neonatal distress: nearest appropriate facility, additional ALS, and medical control.'],
 ['22–31 6/7 weeks: preferential Level 3 NICU destination.','Follow O800 / O801 and local destination capability; contact medical control if uncertain.'],
 ['Report both patients separately.','Birth time, gestational age, presenting part, complications / blood loss, maternal vitals / meds; newborn HR, breathing, resuscitation, and response.']
 ]),source('O801 · DESTINATION',216)+source('O801 · NOTES',217))}<div class="leader-related"><button class="button" data-page="pediatric-arrest">Pediatric cardiac arrest</button></div></div>`;}

export function bindArrestBirth(getState,save){
 document.addEventListener('click',e=>{
  const summary=e.target.closest('.neonatal-code>summary');
  if(summary){const details=summary.parentElement;getState().fields[details.dataset.codeOpen+'-open']=!details.open;save();}
  const b=e.target.closest('[data-leader-scroll]');if(!b)return;
  const target=document.getElementById(b.dataset.leaderScroll);
  if(b.dataset.leaderScroll==='birth-newborn'){getState().fields['birth-neonatal-open']=true;save();target?.querySelector('details')?.setAttribute('open','');}
  target?.scrollIntoView({block:'start'});
 });
 document.addEventListener('toggle',e=>{if(!e.target.isConnected||!e.target.matches('[data-code-open]'))return;getState().fields[e.target.dataset.codeOpen+'-open']=e.target.open;save();},true);
}
